var parsed = JSON.parse(String(sectionsJson));
allSections = JSON.stringify(parsed.sections || []);
pickForm = JSON.stringify({ type: 'form', id: 'pick-form', title: 'Select the sections to generate', fields: (parsed.sections || []).map(function (s, i) { var hint = String(s.content || '').substring(0, 160); return { type: 'field', id: 'keep-' + i, label: (s.title || ('Section ' + (i + 1))), fieldType: 'BOOLEAN', value: true, editable: true, hint: hint }; }) });

var all = JSON.parse(String(allSections));
var sel = [];
for (var i = 0; i < all.length; i++) { if (String(this['keep-' + i]) === 'true') { sel.push({ idx: sel.length, title: all[i].title || ('Section ' + (i + 1)), level: all[i].level || 1, content: String(all[i].content || '') }); } }
selectedJson = JSON.stringify(sel);
ts = String(new Date().getTime());
store = 'wordreport-' + ts;
templateFileName = String(workDir) + '/template_' + ts + '.json';

