var contents = JSON.parse(String(contentsJson));
var pend = JSON.parse(String(pendingJson));
var parts = String(draftsJoined).split('\n<<<SECTION-BREAK>>>\n');
for (var i = 0; i < pend.length; i++) { contents[String(pend[i].idx)] = String(parts[i] || ''); }
contentsJson = JSON.stringify(contents);

var sel = JSON.parse(String(selectedJson));
var contents = JSON.parse(String(contentsJson));
reviewForm = JSON.stringify({ type: 'form', id: 'review-form', title: 'Review the generated sections — edit freely; tick Regenerate to redo one', fields: sel.reduce(function (acc, s) { acc.push({ type: 'field', id: 'content-' + s.idx, label: s.title, fieldType: 'TEXTAREA', value: String(contents[String(s.idx)] || ''), editable: true }); acc.push({ type: 'field', id: 'regen-' + s.idx, label: 'Regenerate "' + s.title + '"', fieldType: 'BOOLEAN', value: false, editable: true }); return acc; }, []) });

var sel = JSON.parse(String(selectedJson));
var contents = JSON.parse(String(contentsJson));
var regen = [];
for (var i = 0; i < sel.length; i++) { var idx = sel[i].idx; var edited = this['content-' + idx]; if (edited !== undefined && edited !== null) { contents[String(idx)] = String(edited); } if (String(this['regen-' + idx]) === 'true') { regen.push(sel[i]); } }
contentsJson = JSON.stringify(contents);
pendingJson = JSON.stringify(regen);
regenCount = regen.length;

var sel = JSON.parse(String(selectedJson));
var contents = JSON.parse(String(contentsJson));
writeArgs = { path: String(workDir) + '/wordreport_' + ts + '.docx', template: String(templateFile), sections: sel.map(function (s) { return { title: s.title, level: s.level, content: String(contents[String(s.idx)] || '') }; }) };
